R=Path(__file__).resolve().parents[2];T=R/'renders/tours_hooh_v1';F=R/'renders/foret_saisons_v1';D=R/'renders/designs_dtef_v4';data={};relative={}
def encode(p):
 b=io.BytesIO();Image.open(p).save(b,format="PNG",optimize=True);return "data:image/png;base64,"+base64.b64encode(b.getvalue()).decode()
def packentry(name,mode,entry,paths):
 images={k:encode(p) for k,p in paths.items()};rel={k:(str(p.relative_to(D)) if 'RAW' in p.parts else str(p.relative_to(R))) for k,p in paths.items()};data.setdefault(name,{})[mode]={**entry,'images':images};relative.setdefault(name,{})[mode]={**entry,'images':rel}
